options.styles:
/* The ATT&CK matrix (attack-matrix.js), Navigator's look. Colours: Grafana's green, yellow, red. */
.atk {
  font-size: 11px;
  line-height: 1.25;
}
.atk-summary {
  margin-bottom: 8px;
}
.atk-legend {
  margin-left: 12px;
}
.atk-legend span {
  display: inline-block;
  padding: 0 6px;
  margin-right: 4px;
  border: 1px solid rgba(128, 128, 128, 0.35);
  border-radius: 2px;
}
.atk-outside {
  margin-bottom: 8px;
  color: #f2495c;
}
.atk-grid {
  display: flex;
  gap: 4px;
  overflow-x: auto;
  align-items: flex-start;
}
.atk-col {
  flex: 1 0 112px;
  min-width: 112px;
}
.atk-tactic {
  font-weight: 600;
  padding: 4px 2px;
  margin-bottom: 4px;
  border-bottom: 2px solid rgba(128, 128, 128, 0.6);
}
.atk-tactic span {
  display: block;
  font-weight: 400;
  opacity: 0.7;
}
.atk-t,
.atk-s {
  display: block;
  padding: 2px 4px;
  margin: 2px 0;
  border: 1px solid rgba(128, 128, 128, 0.35);
  border-radius: 2px;
  color: inherit;
  text-decoration: none;
}
.atk-t:hover,
.atk-s:hover {
  border-color: rgba(128, 128, 128, 0.9);
  text-decoration: none;
}
.atk-subs {
  margin-left: 8px;
}
.atk-s {
  font-size: 10px;
}
.atk-id {
  opacity: 0.7;
}
.atk .tested {
  background: #73bf69;
  color: #111217;
}
.atk .untested {
  background: #fade2a;
  color: #111217;
}
.atk .partial-tested {
  box-shadow: inset 4px 0 0 #73bf69;
}
.atk .partial-untested {
  box-shadow: inset 4px 0 0 #fade2a;
}
.atk .fired {
  outline: 2px solid #f2495c;
  outline-offset: -2px;
}
.atk-fire {
  float: right;
  margin-left: 2px;
  padding: 0 4px;
  border-radius: 6px;
  background: #f2495c;
  color: #fff;
}
